package org.sjbtimdan.linden.data

import app.cash.sqldelight.async.coroutines.awaitAsOneOrNull
import org.sjbtimdan.linden.db.LindenDatabase
import org.sjbtimdan.linden.inflation.seedSeries

/**
 * Seeds the CPI table from the bundled CpiSeedData snapshot (regenerated by
 * tools/gen_cpi.py) the first time a database without stored months is opened.
 * Skipped once any month exists, so a refreshed or hand-edited table is never
 * overwritten.
 */
class CpiDataSeeder(private val database: LindenDatabase) {

    suspend fun seedIfEmpty() {
        val stored = database.cpiQueries.countAll().awaitAsOneOrNull() ?: return
        if (stored > 0L) return
        database.transaction {
            seedSeries().forEach { (currency, series) ->
                series.values.forEachIndexed { index, value ->
                    database.cpiQueries.insertOrReplace(currency.name, series.monthAt(index), value.toLong())
                }
            }
        }
    }
}
